svg.script:
(function () {
  var DUR = 8000;

var heroEl = document.getElementById('nv-hero');
var m0 = document.getElementById('nv-m-0');
var m1 = document.getElementById('nv-m-1');
var m2 = document.getElementById('nv-m-2');
function fmtInt(n) { return Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
function renderAt(p) {
  var s = Math.sin(2 * Math.PI * p);
  if (heroEl) heroEl.textContent = (117.8 + 8.6 * s).toFixed(1) + 'M';
  if (m0) m0.textContent = fmtInt(41681 + 1640 * s);
  if (m1) m1.textContent = fmtInt(24648 + 1120 * s);
  if (m2) m2.textContent = (-9.3 + 4.1 * s).toFixed(1) + '%';
}

  var manual = false;
  window.__seekSvgTime = function (tMs) {
    manual = true;
    renderAt((((tMs / DUR) % 1) + 1) % 1);
  };
  renderAt(0);
  if (typeof requestAnimationFrame === 'function') {
    var t0 = performance.now();
    function loop(now) {
      if (manual) return;
      renderAt(((now - t0) % DUR) / DUR);
      requestAnimationFrame(loop);
    }
    requestAnimationFrame(loop);
  }
})();
